# src/workpeg/config.py
import json
from pathlib import Path


DEFAULT_CONFIG = {
    "function": {
        "entrypoint": "app.main:main",
    },
    "runtime": {
        "default": "cracker",
        "docker": {
            "host": "127.0.0.1",
            "port": 8000,
        },
    },
    "build": {
        "image": None,
    },
}


def deep_merge(base: dict, override: dict) -> dict:
    out = dict(base)
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(out.get(key), dict):
            out[key] = deep_merge(out[key], value)
        else:
            out[key] = value
    return out


def load_config(path: str = "workpeg.json") -> dict:
    cfg_path = Path(path)
    if not cfg_path.exists():
        return DEFAULT_CONFIG.copy()

    data = json.loads(cfg_path.read_text(encoding="utf-8"))
    return deep_merge(DEFAULT_CONFIG, data)


def function_config_path(function_dir) -> Path:
    """The ``workpeg.json`` that describes the function in *function_dir*.

    A function made by ``workpeg function new`` has its own. One made by
    ``workpeg project create`` lives in the peg's ``function/`` folder and
    the peg's manifest sits one folder up, so a folder with none of its own
    reads its parent's when the parent has one. Otherwise the folder's own
    path, which :func:`load_config` reads as the defaults."""
    folder = Path(function_dir)
    own = folder / "workpeg.json"
    if own.exists():
        return own
    parent = folder.resolve().parent / "workpeg.json"
    return parent if parent.exists() else own


def load_function_config(function_dir) -> dict:
    """:func:`load_config` of :func:`function_config_path`."""
    return load_config(function_config_path(function_dir))
